{"code_completion": "module TopModule (
    input        clk,
    input        reset,
    input  [31:0] in,
    output [31:0] out
);

    reg [31:0] out_reg;
    reg [31:0] prev_in;

    always @(posedge clk) begin
        if (reset) begin
            out_reg <= 32'b0;
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
            out_reg <= out_reg | (~in & prev_in);
        end
    end

    assign out = out_reg;

endmodule"}

